INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 7, 7001, "2030/12/17 14:59:59", "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", "2015/12/17 15:00:00", 1, 0.0, -363.0, "キャル", 0, 0.0, 106001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 7, 7002, "2030/12/17 14:59:59", "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", "2015/12/17 15:00:00", 1, 0.0, -363.0, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 7, 7003, "2030/12/17 14:59:59", "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", "2015/12/17 15:00:00", 1, 0.0, -363.0, "ペコリーヌ", 0, 0.0, 105801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 10, 10001, "2030/12/17 14:59:59", "ジュエルを食べ物…\nいえ、貴重品と交換できます！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "ペコリーヌ", 0, 0.0, 105801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 10, 10002, "2030/12/17 14:59:59", "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "キャル", 0, 0.0, 106001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 10, 10003, "2030/12/17 14:59:59", "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", "2015/12/17 15:00:00", 1, 0.0, -363.0, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 2104010, 10, 10004, "2030/12/17 14:59:59", "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", "2015/12/17 15:00:00", 2, 0.0, -363.0, "シェフィ", 0, 0.0, 106401, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 12, 12001, "2030/12/17 14:59:59", "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", "2015/12/17 15:00:00", 1, 0.0, -416.5, "ペコリーヌ", 0, 0.0, 105801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 13, 13001, "2030/12/17 14:59:59", "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", "2015/12/17 15:00:00", 1, 0.0, -363.0, "キャル", 0, 0.0, 106001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 13, 13002, "2030/12/17 14:59:59", "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", "2015/12/17 15:00:00", 1, 0.0, -363.0, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 2104010, 13, 13003, "2030/12/17 14:59:59", "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", "2015/12/17 15:00:00", 2, 0.0, -363.0, "シェフィ", 0, 0.0, 106401, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 13, 13004, "2030/12/17 14:59:59", "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", "2015/12/17 15:00:00", 1, 0.0, -363.0, "ペコリーヌ", 0, 0.0, 105801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 14, 14001, "2030/12/17 14:59:59", "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", "2015/12/17 15:00:00", 1, 0.0, -363.0, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 2104010, 14, 14002, "2030/12/17 14:59:59", "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", "2015/12/17 15:00:00", 2, 0.0, -363.0, "シェフィ", 0, 0.0, 106401, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 14, 14003, "2030/12/17 14:59:59", "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "ペコリーヌ", 0, 0.0, 105801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 14, 14004, "2030/12/17 14:59:59", "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "キャル", 0, 0.0, 106001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 15, 15001, "2030/12/17 14:59:59", "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", "2015/12/17 15:00:00", 1, 0.0, -470.0, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 2104010, 16, 16001, "2030/12/17 14:59:59", "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", "2015/12/17 15:00:00", 2, 0.0, -363.0, "シェフィ", 0, 0.0, 106401, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 16, 16002, "2030/12/17 14:59:59", "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "ペコリーヌ", 0, 0.0, 105801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 16, 16003, "2030/12/17 14:59:59", "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", "2015/12/17 15:00:00", 1, 0.0, -363.0, "キャル", 0, 0.0, 106001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 16, 16004, "2030/12/17 14:59:59", "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", "2015/12/17 15:00:00", 1, 0.0, -363.0, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 17, 17002, "2030/12/17 14:59:59", " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", "2015/12/17 15:00:00", 1, 0.0, -363.0, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 25, 17004, "2030/12/17 14:59:59", "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", "2015/12/17 15:00:00", 1, 0.0, -363.0, "キャル", 0, 0.0, 106001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 25, 17005, "2030/12/17 14:59:59", "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", "2015/12/17 15:00:00", 1, 0.0, -363.0, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 2104010, 25, 17006, "2030/12/17 14:59:59", "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", "2015/12/17 15:00:00", 2, 0.0, -363.0, "シェフィ", 0, 0.0, 106401, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 25, 17007, "2030/12/17 14:59:59", "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", "2015/12/17 15:00:00", 1, 0.0, -363.0, "ペコリーヌ", 0, 0.0, 105801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 18, 18001, "2030/12/17 14:59:59", "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", "2015/12/17 15:00:00", 1, 0.0, -363.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 0, 18, 18002, "2030/12/17 14:59:59", "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (3, 0, 19, 19001, "2030/12/17 14:59:59", "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", "2015/12/17 15:00:00", 1, 0.0, -470.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (4, 0, 19, 19002, "2030/12/17 14:59:59", "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", "2015/12/17 15:00:00", 1, 0.0, -470.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5, 0, 20, 20001, "2030/12/17 14:59:59", "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", "2015/12/17 15:00:00", 1, 0.0, -470.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (6, 0, 20, 20002, "2030/12/17 14:59:59", "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", "2015/12/17 15:00:00", 1, 0.0, -470.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 21, 21001, "2030/12/17 14:59:59", "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "キャル", 0, 0.0, 106001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 21, 21002, "2030/12/17 14:59:59", "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", "2015/12/17 15:00:00", 1, 0.0, -363.0, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 2104010, 21, 21003, "2030/12/17 14:59:59", "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", "2015/12/17 15:00:00", 2, 0.0, -363.0, "シェフィ", 0, 0.0, 106401, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 21, 21004, "2030/12/17 14:59:59", "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "ペコリーヌ", 0, 0.0, 105801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 22, 22001, "2030/12/17 14:59:59", "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", "2015/12/17 15:00:00", 1, 0.0, -430.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 0, 22, 22002, "2030/12/17 14:59:59", "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", "2015/12/17 15:00:00", 1, 0.0, -430.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (3, 0, 23, 23001, "2030/12/17 14:59:59", "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", "2015/12/17 15:00:00", 1, 0.0, -430.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (4, 0, 23, 23002, "2030/12/17 14:59:59", "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", "2015/12/17 15:00:00", 1, 0.0, -430.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 24, 24001, "2030/12/17 14:59:59", "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", "2019/01/31 12:00:00", 1, 4.08, -385.0, "エリコ（バレンタイン）", 10011, 8.0, 109001, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 0, 24, 24002, "2030/12/17 14:59:59", "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", "2019/01/31 12:00:00", 1, 5.0, -385.0, "エリコ（バレンタイン）", 10011, 8.0, 109001, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (3, 0, 24, 24003, "2030/12/17 14:59:59", "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", "2019/01/31 12:00:00", 1, 10.11, -385.0, "エリコ（バレンタイン）", 10011, 8.0, 109001, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (4, 0, 24, 24004, "2030/12/17 14:59:59", "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", "2019/01/31 12:00:00", 1, 4.0, -385.0, "エリコ（バレンタイン）", 10011, 8.0, 109001, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5, 0, 24, 24005, "2030/12/17 14:59:59", "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", "2019/01/31 12:00:00", 1, 6.0, -385.0, "エリコ（バレンタイン）", 10011, 8.0, 109001, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (6, 0, 24, 24006, "2030/12/17 14:59:59", "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", "2019/01/31 12:00:00", 1, 0.0, 0.0, "エリコ（バレンタイン）", 10011, 0.0, 109002, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (7, 0, 24, 24007, "2030/12/17 14:59:59", "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", "2019/01/31 12:00:00", 1, 0.0, 0.0, "エリコ（バレンタイン）", 10011, 0.0, 109002, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (8, 0, 24, 24008, "2030/12/17 14:59:59", "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", "2019/01/31 12:00:00", 1, 0.0, 0.0, "エリコ（バレンタイン）", 10011, 0.0, 109002, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (9, 0, 24, 24009, "2030/12/17 14:59:59", "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", "2019/01/31 12:00:00", 1, 0.0, 0.0, "エリコ（バレンタイン）", 10011, 0.0, 109002, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (10, 0, 24, 24010, "2030/12/17 14:59:59", "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", "2019/01/31 12:00:00", 1, 0.0, 0.0, "エリコ（バレンタイン）", 10011, 0.0, 109002, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 24, 24011, "2030/12/17 14:59:59", "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", "2019/01/31 12:00:00", 1, 2.12, -385.0, "シズル（バレンタイン）", 10011, 8.0, 109101, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 0, 24, 24012, "2030/12/17 14:59:59", "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", "2019/01/31 12:00:00", 5, 4.19, -385.0, "シズル（バレンタイン）", 10011, 8.0, 109101, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (3, 0, 24, 24013, "2030/12/17 14:59:59", "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", "2019/01/31 12:00:00", 2, 2.3, -385.0, "シズル（バレンタイン）", 10011, 8.0, 109101, 4);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (4, 0, 24, 24014, "2030/12/17 14:59:59", "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", "2019/01/31 12:00:00", 1, 0.0, 0.0, "シズル（バレンタイン）", 10011, 0.0, 109102, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5, 0, 24, 24015, "2030/12/17 14:59:59", "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", "2019/01/31 12:00:00", 5, 5.23, -385.0, "シズル（バレンタイン）", 10011, 8.0, 109101, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (6, 0, 24, 24016, "2030/12/17 14:59:59", "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", "2019/01/31 12:00:00", 1, 0.0, 0.0, "シズル（バレンタイン）", 10011, 0.0, 109102, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (7, 0, 24, 24017, "2030/12/17 14:59:59", "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", "2019/01/31 12:00:00", 1, 5.01, -385.0, "シズル（バレンタイン）", 10011, 8.0, 109101, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (8, 0, 24, 24018, "2030/12/17 14:59:59", "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", "2019/01/31 12:00:00", 1, 0.0, 0.0, "シズル（バレンタイン）", 10011, 0.0, 109102, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (9, 0, 24, 24019, "2030/12/17 14:59:59", "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", "2019/01/31 12:00:00", 1, 0.0, 0.0, "シズル（バレンタイン）", 10011, 0.0, 109102, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (10, 0, 24, 24020, "2030/12/17 14:59:59", "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", "2019/01/31 12:00:00", 1, 0.0, 0.0, "シズル（バレンタイン）", 10011, 0.0, 109102, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 2104010, 26, 26001, "2030/12/17 14:59:59", "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", "2015/12/17 15:00:00", 2, 0.0, -363.0, "シェフィ", 0, 0.0, 106401, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 26, 26002, "2030/12/17 14:59:59", "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "ペコリーヌ", 0, 0.0, 105801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 26, 26003, "2030/12/17 14:59:59", "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", "2015/12/17 15:00:00", 1, 0.0, -363.0, "キャル", 0, 0.0, 106001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 26, 26004, "2030/12/17 14:59:59", "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", "2015/12/17 15:00:00", 1, 0.0, -363.0, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 2104010, 27, 27001, "2030/12/17 14:59:59", "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", "2015/12/17 15:00:00", 2, 0.0, -363.0, "シェフィ", 0, 0.0, 106401, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 27, 27002, "2030/12/17 14:59:59", "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "ペコリーヌ", 0, 0.0, 105801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 27, 27003, "2030/12/17 14:59:59", "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "キャル", 0, 0.0, 106001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 27, 27004, "2030/12/17 14:59:59", "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", "2015/12/17 15:00:00", 1, 0.0, -363.0, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 28, 28001, "2030/12/17 14:59:59", "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", "2019/09/24 15:00:00", 1, 0.0, -363.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 0, 28, 28002, "2030/12/17 14:59:59", "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", "2019/09/24 15:00:00", 1, 0.0, -363.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (3, 0, 29, 29001, "2030/12/17 14:59:59", "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", "2019/09/24 15:00:00", 1, 0.0, -409.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (4, 0, 29, 29002, "2030/12/17 14:59:59", "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", "2019/09/24 15:00:00", 1, 0.0, -409.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5, 0, 30, 30001, "2030/12/17 14:59:59", "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", "2019/09/24 15:00:00", 1, 0.0, -409.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (6, 0, 30, 30002, "2030/12/17 14:59:59", "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", "2019/09/24 15:00:00", 1, 0.0, -409.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (7, 0, 31, 31001, "2030/12/17 14:59:59", "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", "2019/10/31 12:00:00", 1, 0.0, -409.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (8, 0, 31, 31002, "2030/12/17 14:59:59", "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", "2019/10/31 12:00:00", 1, 0.0, -409.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 32, 32001, "2020/01/04 4:59:59", "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", "2019/12/20 5:00:00", 1, 0.0, -409.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 0, 32, 32002, "2020/01/04 4:59:59", "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", "2019/12/20 5:00:00", 1, 0.0, -409.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (3, 0, 33, 33001, "2020/01/04 4:59:59", "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", "2019/12/20 5:00:00", 1, 0.0, -409.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (4, 0, 33, 33002, "2020/01/04 4:59:59", "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", "2019/12/20 5:00:00", 1, 0.0, -409.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5, 0, 34, 34001, "2020/01/10 11:59:59", "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", "2020/01/04 5:00:00", 1, 0.0, -409.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (6, 0, 34, 34002, "2020/01/10 11:59:59", "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", "2020/01/04 5:00:00", 1, 0.0, -409.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 38, 38001, "2030/12/17 14:59:59", "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", "2015/12/17 15:00:00", 1, 5.3, -458.0, "ペコリーヌ", 0, 0.0, 105801, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 0, 38, 38002, "2030/12/17 14:59:59", "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", "2015/12/17 15:00:00", 1, 6.5, -458.0, "ペコリーヌ", 0, 0.0, 105801, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (0, 0, 39, 39005, "2020/04/08 23:59:59", "", "2020/04/01", 3, 0.0, 9999.0, "ペコリーヌ", 0, 9999.0, 105801, 3);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 0, 40, 40001, "2030/12/17 14:59:59", "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", "2015/12/17 15:00:00", 1, 0.0, -430.0, "カリン", 0, 0.0, 190801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 2104010, 41, 41001, "2030/12/17 14:59:59", "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", "2015/12/17 15:00:00", 1, 0.0, -363.0, "シェフィ", 0, 0.0, 106401, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 41, 41002, "2030/12/17 14:59:59", "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "ペコリーヌ", 0, 0.0, 105801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 41, 41003, "2030/12/17 14:59:59", "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", "2015/12/17 15:00:00", 1, 0.0, -363.0, "キャル", 0, 0.0, 106001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 41, 41004, "2030/12/17 14:59:59", "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", "2015/12/17 15:00:00", 1, 0.0, -363.0, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 42, 42001, "2030/12/17 14:59:59", "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", "2015/12/17 15:00:00", 1, 0.0, -416.5, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 2104010, 42, 42002, "2030/12/17 14:59:59", "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", "2015/12/17 15:00:00", 1, 0.0, -416.5, "シェフィ", 0, 0.0, 106401, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 42, 42003, "2030/12/17 14:59:59", "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", "2015/12/17 15:00:00", 1, 0.0, -416.5, "ペコリーヌ", 0, 0.0, 105801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 42, 42004, "2030/12/17 14:59:59", "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", "2015/12/17 15:00:00", 1, 0.0, -416.5, "キャル", 0, 0.0, 106001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 43, 43001, "2030/12/17 14:59:59", "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "ペコリーヌ", 0, 0.0, 105801, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 43, 43002, "2030/12/17 14:59:59", "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", "2015/12/17 15:00:00", 1, 0.0, -363.0, "コッコロ", 0, 0.0, 105901, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 43, 43003, "2030/12/17 14:59:59", "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", "2015/12/17 15:00:00", 1, 0.0, -363.0, "キャル", 0, 0.0, 106001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 44, 43004, "2030/12/17 14:59:59", "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", "2015/12/17 15:00:00", 1, 0.0, -416.5, "アメス", 0, 0.0, 123001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 0, 44, 43005, "2030/12/17 14:59:59", "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", "2015/12/17 15:00:00", 1, 0.0, -416.5, "アメス", 0, 0.0, 123001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (3, 0, 45, 43006, "2030/12/17 14:59:59", "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", "2015/12/17 15:00:00", 1, 5.79, -416.5, "アメス", 0, 0.0, 123001, 2);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 46, 46001, "2030/12/17 14:59:59", "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", "2015/12/17 15:00:00", 1, 0.0, -371.5, "アメス", 0, 0.0, 123001, 1);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 0, 47, 47001, "2030/12/17 14:59:59", "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", "2015/12/17 15:00:00", 2, 0.0, -416.5, "シズル", 0, 0.0, 104901, 2);
